const items = $input.all();
const output = [];

for (const item of items) {
    const data = item.json;

    const products = Array.isArray(data.products)
        ? data.products
        : [];

    for (const product of products) {
        output.push({
            json: {
                product_id: product.product_id || null,
                title: product.name || "",
                normalized_title: "",

                price: product.price ?? null,
                original_price: product.original_price ?? null,
                currency: product.currency || null,

                rating: product.rating ?? null,
                sold: product.sold ?? null,
                reviews: product.reviews ?? null,
                shipping: product.shipping ?? null,

                image_url: product.image || "",
                product_url: product.url || "",

                source: data.source || "aliexpress",
                search_query: data.query || ""
            }
        });
    }
}

return output;

const items = $input.all();

const output = [];

for (let i = 0; i < items.length; i++) {

    const item = items[i];
    const data = item.json;

    // Get the LLM response
    let content =
        data.choices?.[0]?.message?.content ||
        data.message?.content ||
        "";

    content = String(content)
        .replace(/```json/gi, "")
        .replace(/```/g, "")
        .trim();

    let parsed;

    try {
        parsed = JSON.parse(content);
    } catch (error) {
        parsed = {
            clean_title: "",
            category: "Other",
            product_type: "",
            brand: null,
            model: null,
            features: [],
            target_use: [],
            compatibility: []
        };
    }

    /*
     * IMPORTANT:
     * The HTTP Request node can replace the original product data
     * with the OpenRouter response.
     *
     * Therefore we retrieve the corresponding product from
     * "Normalize Products" using the same item index.
     */

    let original = {};

    try {
        original = $('Normalize Products').all()[i].json;
    } catch (error) {
        original = {};
    }

    output.push({
      json: {
        title: original.title || "",

        price: original.price ?? null,
        original_price: original.original_price ?? null,
        currency: original.currency || null,

        rating: original.rating ?? null,
        sold: original.sold ?? null,
        reviews: original.reviews ?? null,
        shipping: original.shipping ?? null,

        image_url: original.image_url || "",
        product_url: original.product_url || "",

        source: original.source || "aliexpress",
        search_query: original.search_query || "",

        clean_title: parsed.clean_title || "",
        category: parsed.category || "Other",
        product_type: parsed.product_type || "",
        brand: parsed.brand ?? null,
        model: parsed.model ?? null,

        features: Array.isArray(parsed.features)
            ? parsed.features
            : [],

        target_use: Array.isArray(parsed.target_use)
            ? parsed.target_use
            : [],

        compatibility: Array.isArray(parsed.compatibility)
            ? parsed.compatibility
            : []
      }
    });
}

return output;

