const items = $input.all();

const output = [];

for (let i = 0; i < items.length; i++) {

    const item = items[i];
    const data = item.json;

    // Get LLM response
    let content =
        data.choices?.[0]?.message?.content ||
        "";

    content = String(content)
        .replace(/```json/gi, "")
        .replace(/```/g, "")
        .trim();

    let parsed;

    try {
        parsed = JSON.parse(content);
    } catch (error) {
        parsed = {
            relevance_score: 0,
            is_relevant: false,
            reason: "Failed to parse relevance response"
        };
    }

    // Retrieve original cleaned product
    let original = {};

    try {
        original = $('Parse Product Cleaning').all()[i].json;
    } catch (error) {
        original = {};
    }

    // Normalize score
    let score = Number(parsed.relevance_score);

    if (isNaN(score)) {
        score = 0;
    }

    score = Math.max(0, Math.min(1, score));

    output.push({
        json: {
            ...original,

            relevance_score: score,

            is_relevant:
                parsed.is_relevant === true,

            relevance_reason:
                parsed.reason || ""
        }
    });
}

return output;

const items = $input.all();

const THRESHOLD = 0.75;

return items
    .filter(item => {
        const score = Number(item.json.relevance_score);
        return !isNaN(score) && score >= THRESHOLD;
    })
    .map(item => ({
        json: {
            ...item.json,
            relevance_threshold: THRESHOLD
        }
    }));

