const items = $input.all();

const ASSUMPTIONS = {
    selling_price_multiplier: 2.5,
    payment_fee_rate: 0.03,
    platform_fee_rate: 0.05,
    advertising_cost_rate: 0.15
};

return items.map(item => {
    const p = item.json;

    const price = Number(p.price);
    const originalPrice = Number(p.original_price);

    let discountPercentage = null;

    if (
        Number.isFinite(price) &&
        Number.isFinite(originalPrice) &&
        originalPrice > 0 &&
        originalPrice >= price
    ) {
        discountPercentage =
            ((originalPrice - price) / originalPrice) * 100;
    }

    let estimatedSellingPrice = null;
    let grossProfit = null;
    let grossMargin = null;

    if (Number.isFinite(price) && price > 0) {
        estimatedSellingPrice =
            price * ASSUMPTIONS.selling_price_multiplier;

        grossProfit =
            estimatedSellingPrice - price;

        grossMargin =
            (grossProfit / estimatedSellingPrice) * 100;
    }

    let paymentFee = null;
    let platformFee = null;
    let advertisingCost = null;
    let estimatedNetProfit = null;
    let estimatedNetMargin = null;

    if (
        estimatedSellingPrice !== null &&
        Number.isFinite(price)
    ) {
        paymentFee =
            estimatedSellingPrice *
            ASSUMPTIONS.payment_fee_rate;

        platformFee =
            estimatedSellingPrice *
            ASSUMPTIONS.platform_fee_rate;

        advertisingCost =
            estimatedSellingPrice *
            ASSUMPTIONS.advertising_cost_rate;

        estimatedNetProfit =
            estimatedSellingPrice
            - price
            - paymentFee
            - platformFee
            - advertisingCost;

        estimatedNetMargin =
            (estimatedNetProfit / estimatedSellingPrice) * 100;
    }

    // REPLACEMENT
    // null means "unknown", not zero. Number(null) is 0 and isFinite(0) is
    // true, so an unrated or unsold product was being scored as the worst
    // possible product instead of being left unscored.
    const toNumberOrNull = (value) => {
        if (value === null || value === undefined || value === "") return null;
        const n = Number(value);
        return Number.isFinite(n) ? n : null;
    };

    const rating = toNumberOrNull(p.rating);
    const sold = toNumberOrNull(p.sold);

    let ratingScore = null;

    if (rating !== null && rating > 0 && rating <= 5) {
        ratingScore = (rating / 5) * 100;
    }

    let salesScore = null;

    if (sold !== null && sold > 0) {
        salesScore =
            Math.min(Math.log10(sold + 1) / 5, 1) * 100;
    }

    return {
        json: {
            ...p,

            discount_percentage:
                discountPercentage !== null
                    ? Number(discountPercentage.toFixed(2))
                    : null,

            estimated_selling_price:
                estimatedSellingPrice !== null
                    ? Number(estimatedSellingPrice.toFixed(2))
                    : null,

            gross_profit:
                grossProfit !== null
                    ? Number(grossProfit.toFixed(2))
                    : null,

            gross_margin:
                grossMargin !== null
                    ? Number(grossMargin.toFixed(2))
                    : null,

            payment_fee:
                paymentFee !== null
                    ? Number(paymentFee.toFixed(2))
                    : null,

            platform_fee:
                platformFee !== null
                    ? Number(platformFee.toFixed(2))
                    : null,

            advertising_cost:
                advertisingCost !== null
                    ? Number(advertisingCost.toFixed(2))
                    : null,

            estimated_net_profit:
                estimatedNetProfit !== null
                    ? Number(estimatedNetProfit.toFixed(2))
                    : null,

            estimated_net_margin:
                estimatedNetMargin !== null
                    ? Number(estimatedNetMargin.toFixed(2))
                    : null,

            rating_score:
                ratingScore !== null
                    ? Number(ratingScore.toFixed(2))
                    : null,

            sales_score:
                salesScore !== null
                    ? Number(salesScore.toFixed(2))
                    : null,

            assumptions: {
                selling_price_multiplier:
                    ASSUMPTIONS.selling_price_multiplier,

                payment_fee_rate:
                    ASSUMPTIONS.payment_fee_rate,

                platform_fee_rate:
                    ASSUMPTIONS.platform_fee_rate,

                advertising_cost_rate:
                    ASSUMPTIONS.advertising_cost_rate
            }
        }
    };
});

const items = $input.all();

function clamp(value, min = 0, max = 100) {
    return Math.max(min, Math.min(max, value));
}

function normalizeMargin(margin) {
    if (margin === null || margin === undefined || isNaN(margin)) {
        return null;
    }

    // 40% net margin or more = 100
    return clamp((Number(margin) / 40) * 100);
}

function normalizeProfit(profit) {
    if (profit === null || profit === undefined || isNaN(profit)) {
        return null;
    }

    // 25 TND net profit or more = 100.
    // At 40 the scale ceilinged around 43 TND cost price, so every product
    // above that was identical and the axis stopped ranking anything.
    return clamp((Number(profit) / 25) * 100);
}

function normalizeDiscount(discount) {
    if (discount === null || discount === undefined || isNaN(discount)) {
        return null;
    }

    // 50% discount = full score.
    // We don't reward discounts above this level.
    return clamp((Number(discount) / 50) * 100);
}

return items.map(item => {
    const p = item.json;

    // --------------------------------------------------
    // 1. RELEVANCE
    // --------------------------------------------------

    const relevanceScore =
        Number(p.relevance_score || 0) * 100;


    // --------------------------------------------------
    // 2. OPPORTUNITY
    // --------------------------------------------------

    const opportunityScore =
        clamp(Number(p.opportunity_score || 0));


    // --------------------------------------------------
    // 3. MARKET VALIDATION
    // --------------------------------------------------

    const salesScore =
        p.sales_score !== null &&
        p.sales_score !== undefined
            ? Number(p.sales_score)
            : null;

    const ratingScore =
        p.rating_score !== null &&
        p.rating_score !== undefined
            ? Number(p.rating_score)
            : null;

    let marketScore = null;

    if (
        salesScore !== null &&
        ratingScore !== null
    ) {
        marketScore =
            (salesScore * 0.60) +
            (ratingScore * 0.40);
    } else if (salesScore !== null) {
        marketScore = salesScore;
    } else if (ratingScore !== null) {
        marketScore = ratingScore;
    }


    // --------------------------------------------------
    // 4. PROFITABILITY
    // --------------------------------------------------

    const marginScore =
        normalizeMargin(p.estimated_net_margin);

    const profitScore =
        normalizeProfit(p.estimated_net_profit);

    let profitabilityScore = null;

    if (
        marginScore !== null &&
        profitScore !== null
    ) {
        profitabilityScore =
            (marginScore * 0.70) +
            (profitScore * 0.30);
    } else if (marginScore !== null) {
        profitabilityScore = marginScore;
    } else if (profitScore !== null) {
        profitabilityScore = profitScore;
    }


    // --------------------------------------------------
    // 5. PRODUCT QUALITY
    // --------------------------------------------------

    const discountScore =
        normalizeDiscount(p.discount_percentage);

    let shippingScore = null;

    if (p.shipping) {
        const shippingText =
            String(p.shipping).toLowerCase();

        if (
            shippingText.includes("free") ||
            shippingText.includes("مجاني")
        ) {
            shippingScore = 100;
        } else {
            shippingScore = 50;
        }
    }

    let qualityScore = null;

    const qualityComponents = [];

    if (ratingScore !== null) {
        qualityComponents.push({
            value: ratingScore,
            weight: 0.60
        });
    }

    if (discountScore !== null) {
        qualityComponents.push({
            value: discountScore,
            weight: 0.20
        });
    }

    if (shippingScore !== null) {
        qualityComponents.push({
            value: shippingScore,
            weight: 0.20
        });
    }

    if (qualityComponents.length > 0) {
        const totalWeight =
            qualityComponents.reduce(
                (sum, component) => sum + component.weight,
                0
            );

        qualityScore =
            qualityComponents.reduce(
                (sum, component) =>
                    sum +
                    component.value *
                    component.weight,
                0
            ) / totalWeight;
    }


    // --------------------------------------------------
    // 6. FINAL SCORE
    // --------------------------------------------------

    const components = [];

    if (relevanceScore !== null) {
        components.push({
            value: relevanceScore,
            weight: 0.20
        });
    }

    if (opportunityScore !== null) {
        components.push({
            value: opportunityScore,
            weight: 0.20
        });
    }

    if (marketScore !== null) {
        components.push({
            value: marketScore,
            weight: 0.20
        });
    }

    if (profitabilityScore !== null) {
        components.push({
            value: profitabilityScore,
            weight: 0.25
        });
    }

    if (qualityScore !== null) {
        components.push({
            value: qualityScore,
            weight: 0.15
        });
    }

    const totalWeight =
        components.reduce(
            (sum, component) =>
                sum + component.weight,
            0
        );

    const finalScore =
        components.length > 0
            ? components.reduce(
                (sum, component) =>
                    sum +
                    component.value *
                    component.weight,
                0
            ) / totalWeight
            : 0;


    return {
        json: {
            ...p,

            relevance_component:
                Number(relevanceScore.toFixed(2)),

            opportunity_component:
                Number(opportunityScore.toFixed(2)),

            market_validation_score:
                marketScore !== null
                    ? Number(marketScore.toFixed(2))
                    : null,

            profitability_score:
                profitabilityScore !== null
                    ? Number(profitabilityScore.toFixed(2))
                    : null,

            product_quality_score:
                qualityScore !== null
                    ? Number(qualityScore.toFixed(2))
                    : null,

            final_product_score:
                Number(finalScore.toFixed(2)),

            scoring_weights: {
                relevance: 0.20,
                opportunity: 0.20,
                market_validation: 0.20,
                profitability: 0.25,
                product_quality: 0.15
            }
        }
    };
});

const items = $input.all();

const sorted = [...items].sort((a, b) => {
    const scoreA = Number(a.json.final_product_score ?? 0);
    const scoreB = Number(b.json.final_product_score ?? 0);

    return scoreB - scoreA;
});

return sorted.map((item, index) => ({
    json: {
        ...item.json,
        rank: index + 1
    }
}));
